// ---------- cronograma (Gantt)
const PXD={semana:26,mes:8,trimestre:3,anio:1.2};
function rangoCrono(L,p){let a=p&&p.inicio||"",b=p&&p.fin||"";for(const t of L){const i=t.inicio||t.fin,f=t.fin||t.inicio;if(i&&(!a||i<a))a=i;if(f&&(!b||f>b))b=f}if(!a)a=hoyISO();if(!b||b<a)b=masDias(a,30);return[masDias(lunesDe(a),-7),masDias(b,14)]}
function ganttHtml(filas,a,b,esc_){const px=PXD[PR.escala]||8,dias=Math.round((dDe(b)-dDe(a))/864e5)+1,W=Math.max(400,dias*px),x=f=>Math.round((dDe(f)-dDe(a))/864e5*px),h0=hoyISO();
  let esc2="";if(PR.escala==="semana"){for(let f=lunesDe(a);f<=b;f=masDias(f,7))esc2+=`<div class="gtk" style="left:${x(f)}px;width:${7*px}px">${dDe(f).getDate()} ${MESN[dDe(f).getMonth()]}</div>`}
  else{let f=a.slice(0,8)+"01";if(f<a)f=masDias(f,32).slice(0,8)+"01";for(;f<=b;f=masDias(f,32).slice(0,8)+"01"){const d=dDe(f);esc2+=`<div class="gtk" style="left:${x(f)}px">${PR.escala==="anio"&&d.getMonth()%3?"":MESN[d.getMonth()]+(d.getMonth()===0||PR.escala!=="mes"?" "+String(d.getFullYear()).slice(2):"")}</div>`}}
  return`<div class="gantt"><div class="gnames"><div class="ghead"></div>${filas.map(r=>`<div class="gname" style="--niv:${r.niv||0}" ${r.t?`data-ptv="${esc(r.t.id)}"`:r.p?`data-pr="${esc(r.p.id)}"`:""}>${r.ico||""} ${esc(r.titulo)}</div>`).join("")}</div>
   <div class="gwrap"><div class="gbody" style="width:${W}px"><div class="ghead">${esc2}</div>${h0>=a&&h0<=b?`<div class="ghoy" style="left:${x(h0)}px"></div>`:""}
    ${filas.map(r=>{if(!r.i&&!r.f)return`<div class="grow"></div>`;const i=r.i||r.f,f=r.f||r.i;if(r.hito||i===f&&r.t&&r.t.tipo==="hito")return`<div class="grow"><span class="ghito" style="left:${x(f)-6}px;--fc:${r.c}" title="${esc(r.titulo)} · ${esc(f)}" ${r.t?`data-ptv="${esc(r.t.id)}"`:""}></span></div>`;
      const w=Math.max(px,x(f)-x(i)+px);return`<div class="grow"><span class="gbar ${r.venc?"venc":""}" style="left:${x(i)}px;width:${w}px;--fc:${r.c}" title="${esc(r.titulo)} · ${esc(i)} → ${esc(f)}${r.av!=null?" · "+r.av+"%":""}" ${r.t?`data-ptv="${esc(r.t.id)}"`:r.p?`data-pr="${esc(r.p.id)}"`:""}><span class="gav" style="width:${r.av||0}%"></span><span class="gtx">${esc(r.titulo)}</span></span>${r.dep?`<span class="gdep" style="left:${x(r.dep)}px;width:${Math.max(0,x(i)-x(r.dep))}px"></span>`:""}</div>`}).join("")}</div></div></div>`}
function filasCrono(p){const out=[];const rec=(pad,niv)=>{for(const t of hijosT(p.id,pad)){if(t.estado==="cancelado")continue;const H=S.ptar.filter(x=>x.padre===t.id);let i=t.inicio,f=t.fin;if(H.length&&(!i||!f)){const fs=H.flatMap(h=>[h.inicio,h.fin]).filter(Boolean).sort();i=i||fs[0]||"";f=f||fs[fs.length-1]||""}
    const dep=t.dep?S.ptar.find(x=>x.id===t.dep):null;out.push({t,titulo:t.titulo,niv,ico:PT_TIPOS[t.tipo][0],i,f,c:t.estado==="hecho"?"#1D9E75":p.color||"#378ADD",av:avanceT(t),venc:vencida(t),hito:t.tipo==="hito",dep:dep&&(dep.fin||dep.inicio)});if(PR.abiertos.has("c"+t.id)===false||true)rec(t.id,niv+1)}};rec("",0);return out}
function vPCrono(p){const F=filasCrono(p),[a,b]=rangoCrono(F.map(r=>({inicio:r.i,fin:r.f})),p),sinF=F.filter(r=>!r.i&&!r.f).length;
  return`<div class="filters"><span class="small">Escala</span>${Object.keys(PXD).map(k=>`<button class="b s ${PR.escala===k?"p":""}" data-gesc="${k}">${{semana:"Semanas",mes:"Meses",trimestre:"Trimestres",anio:"Año"}[k]}</button>`).join("")}<span class="sp"></span>${sinF?`<span class="small muted">${sinF} sin fechas (no salen en el cronograma)</span>`:""}</div>
   ${F.length?ganttHtml(F,a,b):'<div class="card"><p class="small muted">Agrega tareas con fecha de inicio y fin para ver el cronograma.</p></div>'}<p class="small muted">La barra se rellena con el avance. La línea roja es hoy. Una línea punteada antes de una barra indica que espera a otra tarea.</p>`}
