// ---------- calendario
function vPCal(p){const f0=PR.cal||hoyISO().slice(0,7)+"-01",d=dDe(f0),y=d.getFullYear(),m=d.getMonth(),ini=lunesDe(f0),T=tareasDe(p.id),R=registrosDe(p);let h=`<div class="dnav"><button class="b s" id="pcP">◀</button><h2 class="dtit">${MESL[m]} ${y}</h2><button class="b s" id="pcN">▶</button></div><div class="mes">${["lun","mar","mié","jue","vie","sáb","dom"].map(x=>`<div class="mh">${x}</div>`).join("")}`;
  for(let i=0;i<42;i++){const f=masDias(ini,i),dd=dDe(f);const tt=T.filter(t=>t.fin===f||(t.inicio===f&&t.inicio!==t.fin)),rr=R.filter(e=>e.fecha===f);
    h+=`<div class="md ${dd.getMonth()!==m?"fuera":""} ${f===hoyISO()?"hoy":""}"><div class="mn">${dd.getDate()}</div>${tt.slice(0,3).map(t=>`<div class="mt click" data-ptv="${esc(t.id)}" style="border-left:3px solid ${vencida(t)?"#c33":p.color||"var(--mod)"}">${t.inicio===f&&t.fin!==f?"▶ ":PT_TIPOS[t.tipo][0]+" "}${esc(t.titulo.slice(0,22))}</div>`).join("")}${rr.slice(0,2).map(e=>`<div class="mt ${e.tipo} click" data-d="${esc(e.id)}">${e.tipo==="evento"?"🤝":"📓"} ${esc((e.titulo||e.texto||"").slice(0,20))}</div>`).join("")}${tt.length+rr.length>5?`<div class="small muted">+${tt.length+rr.length-5}</div>`:""}</div>`}
  return h+"</div>"}
function bindPCal(p){const f0=PR.cal||hoyISO().slice(0,7)+"-01";$("#pcP").onclick=()=>{const d=dDe(f0);d.setMonth(d.getMonth()-1);PR.cal=fISO(d);render()};$("#pcN").onclick=()=>{const d=dDe(f0);d.setMonth(d.getMonth()+1);PR.cal=fISO(d);render()};bindItems($("#view"))}
// ---------- bitácora
function vPBita(p){const R=registrosDe(p),T=tareasDe(p.id).filter(t=>t.hecha).map(t=>({fecha:t.hecha,t}));const L=[...R.map(e=>({fecha:e.fecha,hora:e.hora,e})),...T].sort((a,b)=>(b.fecha+(b.hora||"")).localeCompare(a.fecha+(a.hora||"")));let mes="";
  return`<div class="filters"><button class="b s p" id="pbN">+ Nota</button><button class="b s" id="pbR">+ Reunión</button><span class="sp"></span><span class="small muted">Aquí aparecen las notas y eventos del proyecto${p.tema?`, todo lo que tenga #[${esc(p.tema)}]`:""} y las tareas terminadas.</span></div>
   ${L.length?L.map(x=>{const mm=x.fecha.slice(0,7);const cab=mm!==mes?(mes=mm,`<h3 class="dblq">${MESL[+mm.slice(5)-1]} ${mm.slice(0,4)}</h3>`):"";return cab+(x.e?tarjetaItem({k:"d",fecha:x.e.fecha,hora:x.e.hora,e:x.e}):`<div class="small vrow"><span class="muted">${esc(fechaCorta(x.fecha))}</span><span>✅ Terminada: <a href="#" data-ptv="${esc(x.t.id)}">${esc(x.t.titulo)}</a></span></div>`)}).join(""):'<div class="card"><p class="small muted">Sin registros aún.</p></div>'}`}
