// ---------- archivos y referencias
function vPArch(p){const R=registrosDe(p),adjN=R.flatMap(e=>(e.adjuntos||[]).filter(a=>a.tipo!=="enlace").map(a=>({a,e}))),bib=ligados("p:"+p.id).filter(x=>x.k==="b");
  return`<div class="card"><div class="ih"><h2 style="margin:0">📎 Archivos del proyecto</h2><span class="sp"></span><input type="file" id="paF" multiple></div>${p.adjuntos.length?p.adjuntos.map((a,i)=>`<div class="vrow"><a href="#" data-paa="${i}" style="flex:1">📎 ${esc(a.nombre||"archivo")}</a><span class="small muted">${a.tam?Math.round(a.tam/1024)+" KB":""}</span><button class="b s" data-pax="${i}">✕</button></div>`).join(""):'<p class="small muted">Sube aquí actas, propuestas, informes, cronogramas…</p>'}
    <div class="filters"><input id="paLU" placeholder="https://… (Drive, Dropbox, Overleaf…)" style="flex:2"><input id="paLT" placeholder="Nombre" style="flex:1"><button class="b s" id="paLG">+ Enlace</button></div>${p.enlaces.map((l,i)=>`<div class="vrow small"><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer" style="flex:1">🔗 ${esc(l.titulo||l.url)}</a><button class="b s" data-plx="${i}">✕</button></div>`).join("")}</div>
   ${adjN.length?`<div class="card"><h2>En notas y reuniones</h2>${adjN.map(({a,e})=>`<div class="vrow small"><span class="muted">${esc(fechaCorta(e.fecha))}</span><a href="#" data-d="${esc(e.id)}" style="flex:1">📎 ${esc(a.nombre||"archivo")}</a><span class="muted">${esc(e.titulo||"")}</span></div>`).join("")}</div>`:""}
   <div class="card"><div class="ih"><h2 style="margin:0">📚 Referencias y relaciones</h2><span class="sp"></span><button class="b s" id="paRel">+ Relacionar</button></div>${ligados("p:"+p.id).length?ligados("p:"+p.id).map(x=>`<div class="vrow small click" data-vk="${esc(x.key)}"><span>${x.ico}</span><span style="flex:1">${esc(x.titulo)}</span><span class="muted">${esc(x.sub||"")}</span></div>`).join(""):'<p class="small muted">Relaciona gastos, referencias de la Biblioteca, registros de salud o fichas.</p>'}</div>`}
function bindPArch(p){$("#paF").onchange=async()=>{for(const f of $("#paF").files){try{p.adjuntos.push(await adjDeArchivo(f,hoyISO()))}catch(e){aviso(e.message)}}p.editado=new Date().toISOString();changed();render()};
  document.querySelectorAll("[data-paa]").forEach(a=>a.onclick=ev=>{ev.preventDefault();abrirAdj(p.adjuntos[+a.dataset.paa]).catch(e=>aviso(e.message))});document.querySelectorAll("[data-pax]").forEach(b=>b.onclick=()=>{if(!confirm("¿Quitar este archivo del proyecto?"))return;p.adjuntos.splice(+b.dataset.pax,1);p.editado=new Date().toISOString();changed();render()});
  $("#paLG").onclick=()=>{const u=$("#paLU").value.trim();if(!/^https?:\/\//.test(u)){alert("Pega un enlace que empiece por https://");return}p.enlaces.push({url:u,titulo:$("#paLT").value.trim()});p.editado=new Date().toISOString();changed();render()};
  document.querySelectorAll("[data-plx]").forEach(b=>b.onclick=()=>{p.enlaces.splice(+b.dataset.plx,1);p.editado=new Date().toISOString();changed();render()});
  $("#paRel").onclick=()=>{if(typeof buscaVinDlg==="function")buscaVinDlg("p:"+p.id);else relacionarCon("p:"+p.id)};document.querySelectorAll("[data-vk]").forEach(x=>x.onclick=()=>abrirItem(x.dataset.vk));bindItems($("#view"))}
function relacionarCon(key){dlg("🔗 Relacionar",`<input id="vQ" placeholder="Buscar gasto, nota, referencia, persona…" style="width:100%" autocomplete="off"><div id="vRes"></div>`,[["Cerrar","",()=>{cerrar();render()}]]);
  const pinta=()=>{const L=buscaVin(key).slice(0,40);$("#vRes").innerHTML=L.map(x=>`<div class="vrow small click" data-vadd="${esc(x.key)}"><span>${x.ico}</span><span style="flex:1">${esc(x.titulo)}</span><span class="muted">${esc(x.fecha||"")} ${esc(x.sub||"")}</span></div>`).join("")||'<p class="small muted">Escribe para buscar.</p>';
    document.querySelectorAll("[data-vadd]").forEach(d=>d.onclick=()=>{ligar(key,d.dataset.vadd);changed();aviso("Relacionado");pinta()})};$("#vQ").oninput=pinta;pinta()}
