function vPGente(p){const T=tareasDe(p.id),R=registrosDe(p);
  return`<div class="card"><div class="ih"><h2 style="margin:0">👥 Equipo</h2><span class="sp"></span><button class="b s" id="pgE">Editar</button></div>${p.personas.length?p.personas.map(x=>{const f=fichaDe(x.n,"persona"),mis=T.filter(t=>t.resp&&normK(t.resp)===normK(x.n)),ab=mis.filter(t=>!["hecho","cancelado"].includes(t.estado));
     return`<div class="vrow"><span style="flex:1">${f?`<a href="#" data-fi="${esc(f.id)}">👤 ${esc(x.n)}</a>`:"👤 "+esc(x.n)}${x.rol?` <span class="small muted">· ${esc(x.rol)}</span>`:""}</span><span class="small">${ab.length} pendiente${ab.length===1?"":"s"}${ab.filter(vencida).length?` · <span class="neg">${ab.filter(vencida).length} vencida(s)</span>`:""}</span></div>${ab.length?`<div style="margin-left:22px">${ab.map(filaMini).join("")}</div>`:""}`}).join(""):'<p class="small muted">Agrega a las personas del proyecto (estudiantes, coinvestigadores, familia) en ⚙️.</p>'}</div>
   ${T.some(t=>t.resp&&!p.personas.some(x=>normK(x.n)===normK(t.resp)))?`<div class="card small">También tienen tareas: ${[...new Set(T.filter(t=>t.resp&&!p.personas.some(x=>normK(x.n)===normK(t.resp))).map(t=>t.resp))].map(esc).join(", ")}</div>`:""}`}
function bindPGente(p){$("#pgE").onclick=()=>editarProyecto(p.id);bindItems($("#view"))}
// ---------------------------------------------------------------- editar un elemento
function editarTarea(id,pre){const t0=id?(S.ptar||[]).find(x=>x.id===id):null;if(id&&!t0){aviso("Ya no existe");return}const t=t0?structuredClone(t0):{id:"",proy:PR.id,padre:"",tipo:"tarea",titulo:"",desc:"",estado:"pendiente",prioridad:"",resp:"",inicio:"",fin:"",avance:0,dep:"",orden:0,hecha:"",meta:"",...(pre||{})};
  const p=S.proy.find(x=>x.id===t.proy);if(!p){aviso("Elige un proyecto");return}const otras=tareasDe(p.id).filter(x=>x.id!==t.id),H=t.id?S.ptar.filter(x=>x.padre===t.id):[];
  const gente=[...new Set([...p.personas.map(x=>x.n),...(S.fichas||[]).filter(f=>f.tipo==="persona").map(f=>f.nombre)])];
  dlg(`${PT_TIPOS[t.tipo][0]} ${t0?"Editar":"Nuevo"} · ${esc(nomP(p))}`,`<div class="g2c"><div><label>Tipo</label><select id="etTi">${Object.entries(PT_TIPOS).map(([k,[i,l]])=>`<option value="${k}" ${t.tipo===k?"selected":""}>${i} ${l}</option>`).join("")}</select></div><div><label>Estado</label><select id="etE">${Object.entries(PT_EST).map(([k,[l]])=>`<option value="${k}" ${t.estado===k?"selected":""}>${l}</option>`).join("")}</select></div></div>
   <label>Título</label><input id="etT" value="${esc(t.titulo)}" style="width:100%">
   <div class="g2c"><div><label>Parte de</label><select id="etPa"><option value="">— nivel principal —</option>${otras.filter(x=>x.tipo!=="hito").map(x=>`<option value="${esc(x.id)}" ${t.padre===x.id?"selected":""}>${PT_TIPOS[x.tipo][0]} ${esc(x.titulo.slice(0,60))}</option>`).join("")}</select></div><div><label>Responsable</label><input id="etR" list="etRL" value="${esc(t.resp)}"><datalist id="etRL">${gente.map(g=>`<option value="${esc(g)}">`).join("")}</datalist></div></div>
   <div class="g2c"><div><label>Inicio</label><input type="date" id="etI" value="${esc(t.inicio)}"></div><div><label>${t.tipo==="hito"?"Fecha":"Fecha límite"}</label><input type="date" id="etF" value="${esc(t.fin)}"></div><div><label>Hora</label><input type="time" id="etH" value="${esc(t.hora||"")}"></div></div>
   <div class="g2c"><div><label>Prioridad</label><select id="etPr"><option value="">—</option>${Object.entries(PT_PRI).map(([k,i])=>`<option value="${k}" ${t.prioridad===k?"selected":""}>${i} ${k}</option>`).join("")}</select></div><div><label>Avance ${H.length?"(se calcula de las subtareas)":""}</label><input type="range" id="etAv" min="0" max="100" step="5" value="${t.avance}" ${H.length?"disabled":""}> <span id="etAvT">${H.length?avanceT(t):t.avance}%</span></div></div>
   <div class="g2c"><div><label>Espera a (depende de)</label><select id="etD"><option value="">—</option>${otras.filter(x=>x.id!==t.padre).map(x=>`<option value="${esc(x.id)}" ${t.dep===x.id?"selected":""}>${PT_TIPOS[x.tipo][0]} ${esc(x.titulo.slice(0,50))}</option>`).join("")}</select></div><div><label>Meta o indicador</label><input id="etM" value="${esc(t.meta)}" placeholder="1 artículo, 30 encuestas…"></div></div>
   <label>Notas</label><textarea id="etDe" rows="4" style="width:100%">${esc(t.desc)}</textarea>
   ${H.length?`<div class="small" style="margin-top:6px"><b>Subtareas</b>${H.map(h=>`<div>${h.estado==="hecho"?"✅":"⬜"} <a href="#" data-ptv2="${esc(h.id)}">${esc(h.titulo)}</a>${h.fin?" · "+esc(fechaCorta(h.fin)):""}</div>`).join("")}</div>`:""}
`,
   [...(t0?[["Eliminar","",()=>{const sub=S.ptar.filter(x=>x.padre===t0.id);if(!confirm(sub.length?`¿Eliminar con sus ${sub.length} subtareas?`:"¿Eliminar?"))return;const quitar=new Set([t0.id]);let cam=true;while(cam){cam=false;for(const x of S.ptar)if(quitar.has(x.padre)&&!quitar.has(x.id)){quitar.add(x.id);cam=true}}const ah=new Date().toISOString();for(const q of quitar)S.eliminados.push({id:q,fecha:ah});S.ptar=S.ptar.filter(x=>!quitar.has(x.id));changed();cerrar();render()}],["＋ Subtarea","",()=>{guardar(false);editarTarea(null,{proy:p.id,padre:t.id||ultimaGuardada,tipo:"tarea"})}]]:[]),["Cancelar","",cerrar],["Guardar","p",()=>{if(guardar(true)){cerrar();render()}}]]);$("#dlg").classList.add("ancho");
  let ultimaGuardada="";
  function guardar(){const tit=$("#etT").value.trim();if(!tit){alert("Ponle título");return false}const e=$("#etE").value;Object.assign(t,{tipo:$("#etTi").value,titulo:tit,padre:$("#etPa").value,resp:$("#etR").value.trim(),inicio:$("#etI").value,fin:$("#etF").value,hora:$("#etF").value?$("#etH").value:"",prioridad:$("#etPr").value,avance:+$("#etAv").value||0,dep:$("#etD").value,meta:$("#etM").value.trim(),desc:$("#etDe").value});
    if(e!==t.estado||e==="hecho"&&!t.hecha){t.estado=e;t.hecha=e==="hecho"?(t.hecha||hoyISO()):"";if(e==="hecho")t.avance=100}if(t.inicio&&t.fin&&t.fin<t.inicio){alert("La fecha límite es antes del inicio");return false}
    if(!t.id){t.id=uid();t.creado=new Date().toISOString();t.orden=hijosT(p.id,t.padre).length}ponPt(t);ultimaGuardada=t.id;if(t.resp)asegurarFichas("@["+t.resp+"]");return true}
  $("#etAv").oninput=()=>{$("#etAvT").textContent=$("#etAv").value+"%"};document.querySelectorAll("[data-ptv2]").forEach(a=>a.onclick=ev=>{ev.preventDefault();editarTarea(a.dataset.ptv2)});
  if(t.id&&typeof ponerRelaciones==="function"){try{ponerRelaciones("t:"+t.id)}catch(e){}}setTimeout(()=>{if(!t0)$("#etT").focus()},50)}
// ---------------------------------------------------------------- vistas globales
function vMisTareas(){const h0=hoyISO(),T=(S.ptar||[]).filter(t=>t.tipo!=="objetivo"&&!["hecho","cancelado"].includes(t.estado)&&(S.proy.find(p=>p.id===t.proy)||{}).estado!=="cancelado");
  const g=[["⚠️ Vencidas",T.filter(t=>t.fin&&t.fin<h0)],["📌 Hoy",T.filter(t=>t.fin===h0)],["🗓️ Esta semana",T.filter(t=>t.fin>h0&&t.fin<=masDias(h0,7))],["➡️ Más adelante",T.filter(t=>t.fin>masDias(h0,7))],["📝 Sin fecha",T.filter(t=>!t.fin)]];
  const fila=t=>{const p=S.proy.find(x=>x.id===t.proy)||{};return`<div class="vrow small"><input type="checkbox" data-ptok="${esc(t.id)}"><span style="flex:1" class="click" data-ptv="${esc(t.id)}">${PT_TIPOS[t.tipo][0]} ${t.prioridad?PT_PRI[t.prioridad]+" ":""}${esc(t.titulo)}${t.resp?` · 👤 ${esc(t.resp)}`:""}</span><a href="#" data-pr="${esc(p.id)}" class="chip" style="border-color:${p.color||"var(--line)"}">${esc(nomP(p).slice(0,28))}</a><span class="${t.fin&&t.fin<h0?"neg":""}">${t.fin?esc(fechaCorta(t.fin)):""}</span></div>`};
  return g.filter(([,L])=>L.length).map(([n,L])=>`<div class="card"><h2>${n} <span class="small muted">${L.length}</span></h2>${L.sort((a,b)=>(a.fin||"9").localeCompare(b.fin||"9")).map(fila).join("")}</div>`).join("")||'<div class="card"><p class="small muted">No hay tareas pendientes en tus proyectos.</p></div>'}
function bindMisTareas(){document.querySelectorAll("[data-pr]").forEach(a=>a.onclick=ev=>{ev.preventDefault();abrirProyecto(a.dataset.pr)});bindComunesPt()}
function vCronoGlobal(){const P=(S.proy||[]).filter(p=>["activo","idea","pausado"].includes(p.estado));const F=[];
  for(const p of P){const T=tareasDe(p.id).filter(t=>t.estado!=="cancelado"),fs=[p.inicio,p.fin,...T.flatMap(t=>[t.inicio,t.fin])].filter(Boolean).sort();F.push({p,titulo:nomP(p),ico:PR_EST[p.estado][0],i:p.inicio||fs[0]||"",f:p.fin||fs[fs.length-1]||"",c:p.color||"#378ADD",av:avanceP(p.id)});
    for(const t of T.filter(t=>t.tipo==="hito"||t.tipo==="entregable"))F.push({t,titulo:t.titulo,niv:1,ico:PT_TIPOS[t.tipo][0],i:t.fin,f:t.fin,c:p.color||"#378ADD",hito:true})}
  const [a,b]=rangoCrono(F.map(r=>({inicio:r.i,fin:r.f})),null);
  return`<div class="filters"><span class="small">Escala</span>${Object.keys(PXD).map(k=>`<button class="b s ${PR.escala===k?"p":""}" data-gesc="${k}">${{semana:"Semanas",mes:"Meses",trimestre:"Trimestres",anio:"Año"}[k]}</button>`).join("")}</div>${F.length?ganttHtml(F,a,b):'<div class="card"><p class="small muted">Sin proyectos activos con fechas.</p></div>'}`}
function bindCronoGlobal(){document.querySelectorAll("[data-gesc]").forEach(b=>b.onclick=()=>{PR.escala=b.dataset.gesc;render()});document.querySelectorAll("[data-pr]").forEach(d=>d.onclick=()=>abrirProyecto(d.dataset.pr));bindComunesPt();const g=$(".gwrap"),h0=$(".ghoy");if(g&&h0)g.scrollLeft=Math.max(0,h0.offsetLeft-120)}
// ---------------------------------------------------------------- exportar
function exportarProyecto(p){dlg("📤 Exportar proyecto",`<div class="filters" style="flex-direction:column;align-items:stretch"><button class="b" data-pex="pdf">🖨️ Informe del proyecto (PDF)</button><button class="b" data-pex="xlsx">📗 Tareas en Excel</button><button class="b" data-pex="csv">Tareas en CSV</button><button class="b" data-pex="md">Markdown (para Notion, Docs…)</button></div>`,[["Cerrar","",cerrar]]);
  const filas=()=>{const out=[["Tipo","Título","Nivel","Estado","Responsable","Inicio","Fecha límite","Avance %","Prioridad","Meta","Notas"]];const rec=(pad,n)=>{for(const t of hijosT(p.id,pad)){out.push([PT_TIPOS[t.tipo][1],t.titulo,n,PT_EST[t.estado][0],t.resp,t.inicio,t.fin,avanceT(t)??"",t.prioridad,t.meta,t.desc]);rec(t.id,n+1)}};rec("",0);return out};
  const mdTxt=()=>{let s=`# ${p.nombre}\n\n${[p.area,p.codigo,PR_EST[p.estado][1],p.inicio&&p.fin?p.inicio+" → "+p.fin:""].filter(Boolean).join(" · ")}\n\n`;if(p.objetivo)s+=`**Objetivo general:** ${p.objetivo}\n\n`;if(p.personas.length)s+=`**Equipo:** ${p.personas.map(x=>x.n+(x.rol?" ("+x.rol+")":"")).join(", ")}\n\n`;
    const rec=(pad,n)=>{for(const t of hijosT(p.id,pad)){s+=`${"  ".repeat(n)}- [${t.estado==="hecho"?"x":" "}] ${PT_TIPOS[t.tipo][0]} ${t.titulo}${t.resp?" — "+t.resp:""}${t.fin?" · "+t.fin:""}${t.tipo==="objetivo"?` (${avanceT(t)??0}%)`:""}\n`;rec(t.id,n+1)}};s+="## Objetivos y tareas\n\n";rec("",0);
    const R=registrosDe(p);if(R.length){s+="\n## Bitácora\n\n";for(const e of R.slice(0,200))s+=`### ${e.fecha} ${e.titulo||""}\n${e.priv?"(privada)":e.texto||""}\n\n`}return s};
  document.querySelectorAll("[data-pex]").forEach(b=>b.onclick=async()=>{const f=b.dataset.pex,base=p.nombre.replace(/[^\w\sáéíóúñÁÉÍÓÚÑ-]/g,"").replace(/\s+/g,"_");cerrar();
    if(f==="xlsx"){try{descargar(await escribirExcel([{nombre:"Tareas",filas:filas(),anchos:[12,50,6,12,20,12,12,9,9,24,40]}]),base+".xlsx")}catch(e){alert(e.message)}}
    else if(f==="csv"){const q=v=>`"${String(v??"").replace(/"/g,'""')}"`;descargar(new Blob(["﻿"+filas().map(r=>r.map(q).join(";")).join("\n")],{type:"text/csv"}),base+".csv")}
    else if(f==="md")descargar(new Blob([mdTxt()],{type:"text/markdown"}),base+".md");
    else{const w=window.open("","_blank");if(!w){alert("Permite las ventanas emergentes");return}const T=tareasDe(p.id),h0=hoyISO();
      w.document.write(`<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>${esc(p.nombre)}</title><style>body{font:12px/1.45 Arial,sans-serif;margin:18px;color:#111}h1{font-size:18px;margin:0}h2{font-size:14px;margin:16px 0 6px;border-bottom:2px solid ${p.color||"#378ADD"}}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:3px 6px;text-align:left}th{background:#eee}.n1{padding-left:18px}.n2{padding-left:34px}.n3{padding-left:50px}.v{color:#c00}</style></head><body>
       <h1>${esc(p.nombre)}</h1><p>${esc([p.area,p.codigo,PR_EST[p.estado][1],p.inicio&&p.fin?p.inicio+" → "+p.fin:""].filter(Boolean).join(" · "))} · avance ${avanceP(p.id)??0}% · ${esc(fechaLarga(h0))}</p>${p.objetivo?`<p><b>Objetivo general:</b> ${esc(p.objetivo)}</p>`:""}${p.personas.length?`<p><b>Equipo:</b> ${esc(p.personas.map(x=>x.n+(x.rol?" ("+x.rol+")":"")).join(", "))}</p>`:""}
       <h2>Objetivos, tareas e hitos</h2><table><tr><th>Elemento</th><th>Estado</th><th>Responsable</th><th>Fecha</th><th>Avance</th></tr>${filas().slice(1).map(r=>`<tr><td class="n${Math.min(3,r[2])}">${esc(r[1])}</td><td>${esc(r[3])}</td><td>${esc(r[4])}</td><td class="${r[6]&&r[6]<h0&&r[3]!=="Hecho"?"v":""}">${esc(r[6]||r[5])}</td><td>${esc(r[7])}%</td></tr>`).join("")}</table>
       <h2>Bitácora reciente</h2>${registrosDe(p).slice(0,30).map(e=>`<p><b>${esc(e.fecha)} ${esc(e.titulo||"")}</b><br>${e.priv?"(privada)":esc((e.texto||"").slice(0,600)).replace(/\n/g,"<br>")}</p>`).join("")||"<p>—</p>"}</body></html>`);w.document.close();setTimeout(()=>{w.focus();w.print()},300)}})}
