window.addEventListener("load",()=>{
  const mods=$("#mods");if(mods&&!mods.querySelector('[data-mod="proy"]')){const c=mods.querySelector('[data-mod="cur"]');const h='<button data-mod="proy">🎯 Proyectos</button>';if(c)c.insertAdjacentHTML("beforebegin",h);else mods.insertAdjacentHTML("beforeend",h)}
  const ref=$("#tabsC")||$("#tabsB");if(ref&&!$("#tabsP"))ref.insertAdjacentHTML("afterend",'<nav id="tabsP" hidden><button data-tp="lista" class="on">🎯 Proyectos</button><button data-tp="tareas">☑️ Mis tareas</button><button data-tp="crono">📅 Cronograma</button></nav>');
  $("#tabsP").onclick=ev=>{const b=ev.target.closest("button");if(!b)return;PR.id="";PR.vistaG=b.dataset.tp==="lista"?"":b.dataset.tp;render()};
  // agenda: tareas, hitos y (si se pide) el proyecto como franja
  const ir=window.itemsRango;if(typeof ir==="function")window.itemsRango=function(desde,hasta){const L=ir(desde,hasta);if(TD.filtros.proy!==false&&S){for(const t of S.ptar||[]){if(!t.fin||t.fin<desde||t.fin>hasta||t.tipo==="objetivo"||t.estado==="cancelado")continue;const p=(S.proy||[]).find(x=>x.id===t.proy);if(p&&p.estado!=="cancelado")L.push({k:"pt",fecha:t.fin,hora:t.hora||"",t,p})}L.sort((a,b)=>a.fecha.localeCompare(b.fecha)||(a.hora||"").localeCompare(b.hora||""))}return L};
  const ti=window.tarjetaItem;if(typeof ti==="function")window.tarjetaItem=function(x){if(x&&x.k==="pt"){const {t,p}=x;return`<div class="it ptcard ${t.estado==="hecho"?"hecha":""}" style="--fc:${p.color||"var(--mod)"}"><div class="ih"><input type="checkbox" data-ptok="${esc(t.id)}" ${t.estado==="hecho"?"checked":""}>${t.hora?`<span class="hr2">${esc(t.hora)}</span>`:""}<b class="click" data-ptv="${esc(t.id)}">${PT_TIPOS[t.tipo][0]} ${esc(t.titulo)}</b><span class="sp"></span><a href="#" class="chip" data-pr="${esc(p.id)}">${esc(nomP(p).slice(0,30))}</a></div>${t.resp?`<div class="small muted">👤 ${esc(t.resp)}</div>`:""}</div>`}return ti.apply(this,arguments)};
  const bd=window.bindDiario;if(typeof bd==="function")window.bindDiario=function(){const r=bd.apply(this,arguments);bindComunesPt();document.querySelectorAll("#view [data-pr]:not(.franja),.mini.ptm").forEach(a=>a.onclick=ev=>{ev.preventDefault();ev.stopPropagation();if(a.dataset.pr)abrirProyecto(a.dataset.pr);else editarTarea(a.dataset.pt)});return r};
  // franja del proyecto en la agenda (opcional)
  const vdia=window.vDia;if(typeof vdia==="function")window.vDia=function(){let h=vdia.apply(this,arguments);const P=(S.proy||[]).filter(p=>p.agenda&&p.inicio&&p.fin&&p.inicio<=TD.fecha&&p.fin>=TD.fecha&&TD.filtros.proy!==false);
    if(P.length)h=`<div class="franjas">${P.map(p=>`<div class="franja" style="--fc:${p.color||"var(--mod)"}" data-pr="${esc(p.id)}"><div class="frh"><span class="frt">🎯 ${esc(nomP(p))}</span><span class="frd">${avanceP(p.id)??0}% · hasta ${esc(fechaCorta(p.fin))}</span><span class="frf">▸</span></div></div>`).join("")}</div>`+h;return h};
  const bd2=window.bindDiario;window.bindDiario=function(){const r=bd2.apply(this,arguments);document.querySelectorAll(".franja[data-pr]").forEach(f=>f.onclick=()=>abrirProyecto(f.dataset.pr));return r};
  // notas y reuniones: campo «Proyecto» en el editor del Diario
  const ed=window.editarD;if(typeof ed==="function")window.editarD=function(id,pre){const r=ed.apply(this,arguments);const e0=id?(S.diario||[]).find(x=>x.id===id):null;const P=(S.proy||[]).filter(p=>!["terminado","cancelado"].includes(p.estado)||(e0&&e0.proy===p.id));
    const cur=e0?e0.proy||"":PEND_PROY||"";if(P.length&&!$("#deProy")){const a=$("#deT");if(a)a.insertAdjacentHTML("afterend",`<div class="filters" style="margin:6px 0 0"><label class="small" style="margin:0">🎯 Proyecto <select id="deProy"><option value="">—</option>${P.map(p=>`<option value="${esc(p.id)}" ${cur===p.id?"selected":""}>${esc(nomP(p))}</option>`).join("")}</select></label></div>`)}PEND_PROY="";return r};
  const gd=window.guardarD;if(typeof gd==="function")window.guardarD=function(e,e0){const s=$("#deProy");if(s){if(s.value)e.proy=s.value;else delete e.proy}const r=gd.apply(this,arguments);if(e0&&s&&!s.value){const real=S.diario.find(x=>x.id===e0.id);if(real)delete real.proy}return r};
  // detalle de una nota: enlace a su proyecto
  const vd=window.verD;if(typeof vd==="function")window.verD=function(id){const r=vd.apply(this,arguments);const e=(S.diario||[]).find(x=>x.id===id);if(e&&e.proy&&$("#dlg").open){const p=(S.proy||[]).find(x=>x.id===e.proy);const s=$("#dlgB .small.muted");if(p&&s&&!$("#vdProy")){s.insertAdjacentHTML("afterend",`<div class="small" id="vdProy">🎯 <a href="#" title="${esc(p.nombre)}">${esc(nomP(p))}</a></div>`);$("#vdProy a").onclick=ev=>{ev.preventDefault();cerrar();abrirProyecto(p.id)}}}return r};
  // fichas de personas: sus proyectos y tareas
  const vf=window.vFichas;if(typeof vf==="function")window.vFichas=function(){let h=vf.apply(this,arguments);const f=(S.fichas||[]).find(x=>x.id===TD.ficha);if(f&&f.tipo==="persona"){const P=(S.proy||[]).filter(p=>p.personas.some(x=>normK(x.n)===normK(f.nombre))),T=(S.ptar||[]).filter(t=>t.resp&&normK(t.resp)===normK(f.nombre)&&!["hecho","cancelado"].includes(t.estado));
    if(P.length||T.length)h=h.replace('<div class="g2">',`<div class="card"><h2>🎯 Proyectos</h2>${P.map(p=>`<a href="#" class="chip" data-pr="${esc(p.id)}" title="${esc(p.nombre)}">${esc(nomP(p))}</a>`).join(" ")}${T.map(filaMini).join("")}</div><div class="g2">`)}return h};
});
